    64          public async Task<bool> SendMassEmail(MassEmailModel model)
    65          {
    66              var customization = await _customizationService.GetSettingsAsync();
    67              var email = await _emailService.GetSettingsAsync();
    68              var messagesSent = new List<Task>();
    69              if (model.Bcc)
    70              {
    71                  await SendBccMails(model, customization, email, messagesSent);
    72              }
    73              else
    74              {
    75                  await SendIndividualEmails(model, customization, email, messagesSent);
    76              }
    77  
    78              await Task.WhenAll(messagesSent);
    79  
    80              return true;
    81          }
