    83          private async Task SendBccMails(MassEmailModel model, CustomizationSettings customization, EmailNotificationSettings email, List<Task> messagesSent)
    84          {
    85              var resolver = new NotificationMessageResolver();
    86              var curlys = new NotificationMessageCurlys();
    87  
    88              var validUsers = new List<OmbiUser>();
    89              foreach (var user in model.Users)
    90              {
    91                  var fullUser = await _userManager.Users.FirstOrDefaultAsync(x => x.Id == user.Id);
    92                  if (!fullUser.Email.HasValue())
    93                  {
    94                      _log.LogInformation("User {0} has no email, cannot send mass email to this user", fullUser.UserName);
    95                      continue;
    96                  }
    97  
    98                  validUsers.Add(fullUser);
    99              }
   100              
   101              if (!validUsers.Any())
   102              {
   103                  return;
   104              }
   105  
   106              var firstUser = validUsers.FirstOrDefault();
   107  
   108              var bccAddress = string.Join(',', validUsers.Select(x => x.Email));
   109              curlys.Setup(firstUser, customization);
   110              var template = new NotificationTemplates() { Message = model.Body, Subject = model.Subject };
   111              var content = resolver.ParseMessage(template, curlys);
   112              var msg = new NotificationMessage
   113              {
   114                  Message = content.Message,
   115                  Subject = content.Subject,
   116                  Other = new Dictionary<string, string> { { "bcc", bccAddress } }
   117              };
   118  
   119              messagesSent.Add(_email.SendAdHoc(msg, email));
   120          }
