   132                      continue;
   133                  }
   134                  curlys.Setup(fullUser, customization);
   135                  var template = new NotificationTemplates() { Message = model.Body, Subject = model.Subject };
   136                  var content = resolver.ParseMessage(template, curlys);
   137                  var msg = new NotificationMessage
   138                  {
   139                      Message = content.Message,
   140                      To = fullUser.Email,
   141                      Subject = content.Subject
   142                  };
   143                  messagesSent.Add(DelayEmail(msg, email));
   144                  _log.LogInformation("Sent mass email to user {0} @ {1}", fullUser.UserName, fullUser.Email);
   145              }
   146          }
