   148          /// <summary>
   149          /// This will add a 2 second delay, this is to help with concurrent connection limits
   150          /// <see href="https://github.com/Ombi-app/Ombi/issues/4377"/>
   151          /// </summary>
   152          private async Task DelayEmail(NotificationMessage msg, EmailNotificationSettings email)
   153          {
   154              await Task.Delay(2000);
   155              await _email.SendAdHoc(msg, email);
